import {validConfig,SCHOOL,today} from './core.js';
const uuid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^(crypto.getRandomValues(new Uint8Array(1))[0]&(15>>(Number(c)/4)))).toString(16));
let refreshPromise=null;
export const store={config:window.SCHOOL_CONFIG||{},session:null,profile:null,demo:false,records:[],settings:{school_name:SCHOOL,academic_year:String(new Date().getFullYear()+543),director_name:''}};
try{const c=JSON.parse(localStorage.getItem('ssw_config')||'null');if(validConfig(c))store.config=c;store.session=JSON.parse(sessionStorage.getItem('ssw_session')||'null')}catch{}
export const configured=()=>validConfig(store.config);
export function saveConfig(c){if(!validConfig(c))throw Error('ใช้ Project URL (*.supabase.co) และ Publishable key หรือ anon key เท่านั้น');store.config=c;localStorage.setItem('ssw_config',JSON.stringify(c));sessionStorage.removeItem('ssw_session');store.session=null;store.profile=null;store.demo=false}
function setSession(s){store.session=s;if(s)sessionStorage.setItem('ssw_session',JSON.stringify(s));else sessionStorage.removeItem('ssw_session')}
async function raw(path,{method='GET',body,token,headers={}}={}){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(store.config.supabaseUrl+path,{method,headers:{apikey:store.config.supabaseAnonKey,...(token?{Authorization:'Bearer '+token}:{}),'Content-Type':'application/json',...headers},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:controller.signal});const text=await response.text();let value=null;try{value=text?JSON.parse(text):null}catch{throw Error('ฐานข้อมูลตอบกลับในรูปแบบที่ไม่ถูกต้อง')}if(!response.ok){const message=value?.msg||value?.message||value?.error_description||value?.error||'เชื่อมต่อฐานข้อมูลไม่สำเร็จ';throw Error(message)}return value}finally{clearTimeout(timer)}}
async function token(){const s=store.session;if(!s)throw Error('กรุณาเข้าสู่ระบบ');if(s.expires_at*1000<Date.now()+60000){if(!refreshPromise)refreshPromise=raw('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:s.refresh_token}}).then(v=>{setSession({...v,expires_at:Math.floor(Date.now()/1000)+v.expires_in});return v.access_token}).catch(e=>{setSession(null);throw e}).finally(()=>{refreshPromise=null});return refreshPromise}return s.access_token}
export async function request(path,options={}){return raw(path,{...options,token:await token()})}
export async function signIn(email,password){if(!configured())throw Error('ยังไม่ได้เชื่อมต่อ Supabase');const s=await raw('/auth/v1/token?grant_type=password',{method:'POST',body:{email,password}});setSession({...s,expires_at:Math.floor(Date.now()/1000)+s.expires_in});store.demo=false;await restore()}
export async function signUp(email,password,display_name){if(!configured())throw Error('ยังไม่ได้เชื่อมต่อ Supabase');return raw('/auth/v1/signup',{method:'POST',body:{email,password,data:{display_name}}})}
export async function restore(){if(!store.session)return false;const user=await request('/auth/v1/user');const p=await request('/rest/v1/school_profiles?id=eq.'+user.id+'&select=*');if(!p?.length)throw Error('ยังไม่พบโครงสร้างฐานข้อมูลหรือโปรไฟล์ผู้ใช้');store.profile=p[0];store.profile.email=user.email;if(!store.profile.active)throw Error('บัญชีถูกระงับ กรุณาติดต่อผู้ดูแลระบบ');if(store.profile.role!=='pending'){const settings=await request('/rest/v1/school_settings?select=*');store.settings={...store.settings,...settings[0]}}return true}
export async function signOut(){if(!store.demo&&store.session)try{await request('/auth/v1/logout',{method:'POST'})}catch{}setSession(null);store.profile=null;store.records=[];store.demo=false}
export async function loadRecords(){if(store.demo)return store.records;const all=[];for(let offset=0;offset<50000;offset+=1000){const rows=await request('/rest/v1/school_records?academic_year=eq.'+encodeURIComponent(store.settings.academic_year)+'&select=*&order=created_at.desc&offset='+offset+'&limit=1000');all.push(...rows);if(rows.length<1000){store.records=all;return all}}throw Error('ข้อมูลมีมากกว่า 50,000 รายการ กรุณาแยกปีการศึกษาหรือปรับระบบแบ่งหน้า')}
export const records=kind=>store.records.filter(r=>r.record_type===kind);
export async function saveRecord(kind,data,old=null){const body={record_type:kind,academic_year:String(data.academic_year||store.settings.academic_year),class_id:data.class_id||(data.class_level?data.class_level+'/'+(data.room||'1'):''),data};if(store.demo){if(old){const idx=store.records.findIndex(r=>r.id===old.id);store.records[idx]={...old,...body,version:old.version+1}}else store.records.unshift({...body,id:uuid(),created_by:'demo',created_at:new Date().toISOString(),version:1});return}if(old){const result=await request('/rest/v1/school_records?id=eq.'+old.id+'&version=eq.'+old.version,{method:'PATCH',body:{academic_year:body.academic_year,class_id:body.class_id,data},headers:{Prefer:'return=representation'}});if(!result?.length)throw Error('ข้อมูลถูกแก้ไขโดยผู้ใช้อื่นหรือไม่มีสิทธิ์ กรุณาโหลดใหม่')}else await request('/rest/v1/school_records',{method:'POST',body,headers:{Prefer:'return=representation'}})}
export async function deleteRecord(row){if(store.demo){store.records=store.records.filter(r=>r.id!==row.id);return}const result=await request('/rest/v1/school_records?id=eq.'+row.id+'&version=eq.'+row.version,{method:'DELETE',headers:{Prefer:'return=representation'}});if(!result?.length)throw Error('ข้อมูลถูกแก้ไขหรือคุณไม่มีสิทธิ์ลบ')}
export async function rpc(name,body){return request('/rest/v1/rpc/'+name,{method:'POST',body})}
export function startDemo(){store.demo=true;store.profile={id:'demo',display_name:'ผู้ดูแลระบบ (สาธิต)',role:'admin',homeroom:''};store.settings={school_name:SCHOOL,academic_year:'2569',director_name:''};store.records=[];const add=(kind,data)=>{const r={id:uuid(),record_type:kind,data,academic_year:'2569',class_id:data.class_id||(data.class_level?data.class_level+'/'+(data.room||'1'):''),created_by:'demo',created_at:new Date().toISOString(),version:1};store.records.push(r);return r};const names=[['กานต์','ใจดี'],['ณิชา','แสงทอง'],['ธนพล','มีสุข'],['ปวีณ์','พัฒนาดี'],['พิมพ์ชนก','รักษ์เรียน'],['ภูมิ','สายใจ'],['มนัส','ตั้งใจ'],['วรัญญา','พูนสุข']];for(let level=1;level<=6;level++)for(let i=0;i<8;i++)add('Students',{student_id:String(1000+level*10+i),prefix:i%2?'ด.ญ.':'ด.ช.',first_name:names[i][0],last_name:names[i][1],class_level:'ป.'+level,room:'1',roll_no:i+1,status:'กำลังศึกษา',academic_year:'2569'});for(let i=1;i<=6;i++){add('Teachers',{teacher_id:'T0'+i,prefix:'ครู',first_name:'ครูตัวอย่าง '+i,last_name:'เพื่อสาธิต',position:'ครู',homeroom:'ป.'+i+'/1',status:'active'});add('Classrooms',{class_id:'ป.'+i+'/1',class_level:'ป.'+i,room:'1',academic_year:'2569'});add('Attendance',{date:today(),class_id:'ป.'+i+'/1',total:8,present:7,late:0,leave:1,absent:0,marks:'{}'})}const p=add('Projects',{name:'พัฒนาการเรียนรู้และทักษะผู้เรียน',plan:'พัฒนาคุณภาพผู้เรียน',budget_alloc:120000,budget_activity:30000,responsible:'ฝ่ายวิชาการ',status:'อนุมัติ'});add('Projects',{name:'โรงเรียนสีเขียวและสิ่งแวดล้อม',plan:'บริหารทั่วไป',budget_alloc:45000,budget_activity:10000,responsible:'ฝ่ายบริหารทั่วไป',status:'ร่าง'});add('ProjRequests',{proj_id:p.id,proj_name:p.data.name,description:'อุปกรณ์กิจกรรมการเรียนรู้',amount_request:12500,status:'ยื่นแล้ว',requested_name:'ครูตัวอย่าง',request_date:today()});add('Events',{title:'ประชุมครูและบุคลากรประจำเดือน',start_date:today(),location:'ห้องประชุมโรงเรียน',category:'ประชุม'});add('Events',{title:'กิจกรรมส่งเสริมนิสัยรักการอ่าน',start_date:today(),location:'ห้องสมุด',category:'กิจกรรมนักเรียน'});add('Books',{title:'อ่านสนุก คิดสร้างสรรค์',author:'หนังสือตัวอย่าง',category:'ความรู้ทั่วไป',copies_total:10,copies_available:10});add('Supplies',{name:'กระดาษ A4',unit:'รีม',current_stock:50,min_stock:10,max_stock:100});return store.records}
